            cc = [fit([rows[i] for i in use],[states[i+1][d] for i in use]) for d in range(2)]
            if cc[0] is not None:
                loo.append(sum((states[omit+1][d]-sum(rows[omit][j]*cc[d][j] for j in range(len(rows[omit]))))**2 for d in range(2))**0.5)
        result.append({'kind':kind,'coefficients':coeff,'residuals':residual,'max_loo_error':max(loo) if loo else None})
    return {'fits':result,'radii':[sum(z*z for z in s)**0.5 for s in states]}
